/**
 * Cheerio-lite for TVBox Spider
 * Simplified HTML parser for iOS QuickJS/JavaScriptCore
 */
(function(global) {
    'use strict';

    function CheerioLite(html) {
        this.html = html || '';
        this.document = this.parseHTML(this.html);
    }

    CheerioLite.prototype.parseHTML = function(html) {
        // 简化的HTML解析器
        var doc = {
            children: [],
            find: function(selector) {
                return querySelectorAll(this, selector);
            },
            findOne: function(selector) {
                return querySelector(this, selector);
            }
        };
        
        // 解析基本标签
        var tagRegex = /<([a-zA-Z][^>]*)>([^]*?)<\/\1>/g;
        var match;
        while ((match = tagRegex.exec(html)) !== null) {
            var tagName = match[1].split(' ')[0];
            var attrs = {};
            var attrMatch;
            var attrRegex = /(\w+)=["']([^"']+)["']/g;
            while ((attrMatch = attrRegex.exec(match[1])) !== null) {
                attrs[attrMatch[1]] = attrMatch[2];
            }
            
            doc.children.push({
                tagName: tagName,
                attrs: attrs,
                innerHTML: match[2],
                text: match[2].replace(/<[^>]+>/g, '')
            });
        }
        
        return doc;
    };

    function querySelectorAll(doc, selector) {
        var results = [];
        var parts = selector.split(/\s+/);
        
        doc.children.forEach(function(child) {
            if (matchesSelector(child, parts[0])) {
                if (parts.length === 1) {
                    results.push(child);
                } else {
                    // 简化：递归查找子元素
                    findDeep(child, parts.slice(1), results);
                }
            }
        });
        
        return results;
    }

    function querySelector(doc, selector) {
        var results = querySelectorAll(doc, selector);
        return results.length > 0 ? results[0] : null;
    }

    function matchesSelector(elem, selector) {
        if (selector.startsWith('.')) {
            return elem.attrs && elem.attrs.class && elem.attrs.class.includes(selector.slice(1));
        }
        if (selector.startsWith('#')) {
            return elem.attrs && elem.attrs.id === selector.slice(1);
        }
        return elem.tagName === selector.toLowerCase();
    }

    function findDeep(elem, parts, results) {
        if (!elem.children) return;
        
        elem.children.forEach(function(child) {
            if (matchesSelector(child, parts[0])) {
                if (parts.length === 1) {
                    results.push(child);
                } else {
                    findDeep(child, parts.slice(1), results);
                }
            }
        });
    }

    // jQuery风格的API
    function $(selector, context) {
        if (typeof selector === 'string' && selector.startsWith('<')) {
            // 创建新的Cheerio对象
            return new CheerioLite(selector);
        }
        
        // 选择器模式
        var doc = context || { children: [] };
        if (typeof context === 'string') {
            doc = new CheerioLite(context).document;
        }
        
        var elems = querySelectorAll(doc, selector);
        return {
            length: elems.length,
            get: function(i) { return elems[i]; },
            text: function() { 
                return elems.map(function(e) { return e.text || ''; }).join(''); 
            },
            html: function() { 
                return elems.map(function(e) { return e.innerHTML || ''; }).join(''); 
            },
            attr: function(name) {
                return elems.length > 0 ? (elems[0].attrs[name] || '') : '';
            },
            find: function(sel) {
                var allChildren = [];
                elems.forEach(function(e) {
                    if (e.children) {
                        e.children.forEach(function(c) {
                            if (matchesSelector(c, sel)) allChildren.push(c);
                        });
                    }
                });
                return {
                    length: allChildren.length,
                    get: function(i) { return allChildren[i]; },
                    text: function() { return allChildren.map(function(e) { return e.text || ''; }).join(''); },
                    attr: function(name) { return allChildren.length > 0 ? (allChildren[0].attrs[name] || '') : ''; }
                };
            },
            each: function(callback) {
                elems.forEach(function(e, i) {
                    callback(i, e);
                });
                return this;
            },
            map: function(callback) {
                return elems.map(function(e, i) {
                    return callback(e, i);
                });
            }
        };
    }

    // 加载HTML
    $.load = function(html) {
        return new CheerioLite(html);
    };

    global.cheerio = { load: $.load };
    global.$ = $;

})(this);
